import http from 'k6/http';import {check} from 'k6';import {baseURL,scenarioOptions} from '../lib/config.js';import {routeSuccess,secretLeaks} from '../lib/metrics.js';
export const options=scenarioOptions('security',['route_success','secret_leaks']);function leak(r,s){return `${r.body}${JSON.stringify(r.headers)}`.includes(s)}export default function(){const s=__ENV.SECRET||'known-k6-secret',cases=[['missing_user','/auth/user','',401],['invalid_user','/auth/user','invalid',401],['forbidden_admin','/auth/admin',`user:${s}`,403],['success_user','/auth/user',`user:${s}`,200],['success_admin','/auth/admin',`admin:${s}`,200]];let ok=true;for(const [name,path,token,status]of cases){const r=http.get(baseURL()+path,{headers:token?{Authorization:`Bearer ${token}`}:{}}),l=leak(r,s);secretLeaks.add(l?1:0,{operation:name});ok=check(r,{[`security ${name} exact status`]:x=>x.status===status,[`security ${name} request id`]:x=>Boolean(x.headers['X-Request-Id']||x.headers['X-Request-ID']),[`security ${name} secret absent`]:()=>!l})&&ok}const m=http.get(`${baseURL()}/__test/metrics`);ok=check(m,{'security metrics status 200':r=>r.status===200,'security active requests zero':r=>r.json().active_requests===0,'security SSE connections zero':r=>r.json().sse_connections===0,'security WS connections zero':r=>r.json().ws_connections===0})&&ok;routeSuccess.add(ok,{route_family:'security',operation:'auth_matrix'});}
